const extras={"lipidos":[["¿Qué componente de un fosfolípido interactúa con el agua?","La cabeza polar","Las colas hidrocarbonadas","El glicerol sin fosfato","El anillo esteroide","La cabeza con fosfato es hidrofílica."],["¿Qué característica distingue a un ácido graso insaturado?","Presenta uno o más dobles enlaces","No contiene carbono","Tiene siempre tres grupos amino","Es soluble en agua","Los dobles enlaces generan insaturación."],["¿Qué reserva energética aportan principalmente los triglicéridos?","Energía de largo plazo","Información hereditaria","Contracción inmediata","Transmisión de impulsos","Los triglicéridos almacenan energía concentrada."],["¿Qué molécula pertenece al grupo de los esteroides?","Colesterol","Almidón","Hemoglobina","Celulosa","El colesterol posee estructura de anillos fusionados."],["¿Qué función cumple el tejido adiposo subcutáneo?","Aislamiento térmico","Conducción nerviosa","Producción de bilis","Filtración renal","La grasa subcutánea reduce la pérdida de calor."],["¿Qué diferencia a una grasa saturada?","No presenta dobles enlaces en sus cadenas","Tiene muchos dobles enlaces","Está formada por aminoácidos","Es un polisacárido","Los ácidos grasos saturados carecen de dobles enlaces C=C."],["¿Qué lípido contribuye a regular la fluidez de membrana animal?","Colesterol","Cera de abeja","Triglicérido almacenado","Glucógeno","El colesterol modula el empaquetamiento de fosfolípidos."],["¿Qué enlace se forma al unir glicerol y ácidos grasos?","Enlace éster","Enlace peptídico","Enlace glucosídico","Enlace fosfodiéster","La esterificación une grupos hidroxilo y carboxilo."],["¿Por qué los lípidos son insolubles en agua?","Predominan regiones apolares","Son moléculas totalmente iónicas","Contienen muchos grupos cargados","Se convierten en sales","Las regiones hidrocarbonadas no establecen interacciones favorables con el agua."],["¿Qué resultado puede indicar un perfil lipídico?","Concentraciones de colesterol y triglicéridos","Cantidad de neuronas","Capacidad pulmonar","Número de cromosomas","El perfil lipídico mide grasas circulantes."],["¿Qué función cumplen los fosfolípidos en una célula?","Formar la barrera selectiva de membrana","Almacenar oxígeno en sangre","Copiar ADN","Descomponer almidón","La bicapa fosfolipídica delimita la célula y regula el intercambio."],["¿Qué estructura caracteriza a muchos esteroides?","Cuatro anillos de carbono fusionados","Una cadena de aminoácidos","Una doble hélice","Tres moléculas de glucosa","Los esteroides comparten un núcleo de cuatro anillos."],["Una hoja con cutícula cerosa pierde menos agua porque la cera:","Reduce la evaporación superficial","Aumenta la fotosíntesis directamente","Produce glucosa","Abre los estomas","La capa hidrofóbica limita la pérdida de agua."],["Si una dieta aporta exceso energético, los triglicéridos pueden:","Almacenarse en tejido adiposo","Convertirse siempre en ADN","Eliminarse por pulmones","Transformarse en anticuerpos","El organismo almacena energía excedente como grasa."],["¿Por qué los fosfolípidos forman espontáneamente bicapas?","Sus cabezas hidrofílicas miran al agua y colas se agrupan","Todas sus partes atraen agua","Son proteínas fibrosas","Tienen carga idéntica en toda la molécula","La naturaleza anfipática favorece la bicapa en medio acuoso."]],"proteinas":[["¿Qué parte del aminoácido varía entre los distintos aminoácidos?","Grupo R","Grupo amino","Grupo carboxilo","Carbono alfa","El grupo R determina propiedades y distingue aminoácidos."],["¿Qué significa que un aminoácido sea esencial?","Debe obtenerse mediante la dieta","El cuerpo lo produce siempre","No forma proteínas","Solo existe en plantas","Los aminoácidos esenciales no se sintetizan en cantidad suficiente."],["¿Qué ocurre al formarse un enlace peptídico?","Se libera una molécula de agua","Se libera oxígeno molecular","Se duplica el ADN","Se forma glucosa","La unión es una reacción de condensación."],["¿Qué nivel estructural describe hélices alfa y láminas beta?","Estructura secundaria","Primaria","Terciaria","Cuaternaria","La estructura secundaria corresponde a plegamientos locales."],["¿Qué estabiliza principalmente la estructura terciaria?","Interacciones entre grupos R","Solo enlaces glucosídicos","Unión de nucleótidos","Enlaces entre ácidos grasos","Puentes disulfuro e interacciones entre cadenas laterales estabilizan el plegamiento."],["La hemoglobina es un ejemplo de proteína:","Globular y conjugada","Fibrosa simple","Carbohidrato","Lípido de membrana","La hemoglobina es globular y contiene grupos hemo."],["¿Qué caracteriza a una heteroproteína?","Posee una parte proteica y un componente no proteico","Solo contiene aminoácidos","Carece de estructura","Está formada por glucosa","Incluye un grupo prostético además de la proteína."],["¿Cuál es una función de la caseína?","Reserva de aminoácidos en la leche","Transporte de oxígeno","Contracción muscular","Replicación de ADN","La caseína es una fosfoproteína abundante en la leche."],["¿Qué proteína da resistencia al cabello y uñas?","Queratina","Colágeno sanguíneo","Insulina","Amilasa","La queratina es estructural y fibrosa."],["¿Qué puede causar una desnaturalización?","Pérdida de la conformación y función","Cambio del número de protones","Formación de un nuevo gen","Conversión directa en lípido","Temperatura o pH extremos alteran la conformación proteica."],["¿Qué nivel estructural aparece cuando se asocian varias cadenas polipeptídicas?","Cuaternaria","Primaria","Secundaria","No existe nivel estructural","La estructura cuaternaria organiza varias subunidades."],["¿Qué relación existe entre secuencia y función proteica?","La secuencia condiciona el plegamiento y la función","La secuencia no influye","Solo importa el tamaño celular","La función depende únicamente del agua","La secuencia de aminoácidos condiciona su conformación."],["Una dieta muy deficiente en proteínas durante la infancia puede provocar:","Kwashiorkor","Escorbuto por falta de vitamina C","Raquitismo por falta de vitamina D","Anemia por hierro necesariamente","Kwashiorkor se asocia a déficit proteico grave."],["¿Por qué una enzima es específica?","Su sitio activo reconoce determinados sustratos","Tiene siempre forma lineal","Está hecha de lípidos","Actúa sobre cualquier sustancia","La forma y propiedades del sitio activo determinan especificidad."],["¿Qué distingue a una proteína fibrosa?","Forma alargada con función estructural frecuente","Siempre transporta oxígeno","Es soluble y globular en todos los casos","No contiene aminoácidos","Las proteínas fibrosas suelen aportar soporte y resistencia."]],"fotosintesis":[["¿En qué orgánulo ocurre la fotosíntesis en plantas?","Cloroplasto","Mitocondria","Ribosoma","Lisosoma","Los cloroplastos contienen tilacoides y estroma."],["¿Dónde ocurren las reacciones dependientes de luz?","Membranas de los tilacoides","Estroma exclusivamente","Citoplasma","Membrana nuclear","Los fotosistemas y la cadena transportadora están en tilacoides."],["¿Qué productos energéticos generan las reacciones luminosas?","ATP y NADPH","Glucógeno y urea","ADN y ARN","Pepsina y lipasa","ATP y NADPH alimentan el ciclo de Calvin."],["¿Dónde ocurre el ciclo de Calvin?","Estroma del cloroplasto","Lumen tilacoidal","Núcleo","Membrana plasmática","Las reacciones de fijación de carbono ocurren en el estroma."],["¿Cuál es el producto orgánico inicial estable de la fijación de CO₂ en plantas C3?","3-fosfoglicerato","Oxalacetato","Piruvato","Acetil-CoA","La vía C3 produce 3-fosfoglicerato como primer producto estable."],["¿Qué ventaja presentan las plantas C4 en ambientes cálidos?","Concentran CO₂ y reducen fotorrespiración","No requieren luz","No utilizan agua","No realizan ciclo de Calvin","La separación espacial ayuda a concentrar CO₂."],["¿Qué adaptación caracteriza a las plantas CAM?","Abren estomas de noche y fijan CO₂ inicialmente","Abren estomas solo al mediodía","Carecen de cloroplastos","No producen carbohidratos","La fijación nocturna reduce pérdida de agua."],["¿Qué gas entra por los estomas para la fotosíntesis?","Dióxido de carbono","Oxígeno como fuente de carbono","Nitrógeno molecular","Metano exclusivamente","El CO₂ aporta el carbono de las moléculas orgánicas."],["¿Qué pigmento participa principalmente en la captación de luz?","Clorofila","Hemoglobina","Melanina","Queratina","La clorofila absorbe luz en regiones del espectro visible."],["¿Qué ocurre en la fotólisis del agua?","Se obtienen electrones, protones y oxígeno","Se consume glucosa","Se fija nitrógeno","Se libera dióxido de carbono","El agua se oxida durante las reacciones luminosas."],["¿Por qué la fotorrespiración reduce la eficiencia?","Consume energía y libera CO₂ sin producir azúcares netos","Produce grandes cantidades de glucosa","Sustituye totalmente al ciclo de Calvin","Genera oxígeno a partir de glucosa","La ruta recupera carbono con gasto energético."],["¿Qué fuente de energía impulsa la fotosíntesis?","Luz solar","Energía de enlaces peptídicos","Calor del núcleo terrestre","Energía de la gravedad","La energía luminosa excita electrones en los pigmentos."],["¿Qué organismos pueden realizar fotosíntesis anoxigénica?","Algunas bacterias fotosintéticas","Todos los mamíferos","Hongos superiores","Todas las plantas terrestres","Ciertas bacterias utilizan donadores de electrones distintos del agua."],["Si una planta permanece varios días sin luz, ¿qué proceso disminuye primero?","Producción de ATP y NADPH fotosintéticos","Absorción de minerales por raíces de forma absoluta","Respiración celular a cero","Transporte de agua a cero","Sin luz se detienen las reacciones fotoquímicas."],["¿Cuál es el balance general de la fotosíntesis oxigénica?","Convierte energía luminosa en energía química y fija carbono","Transforma oxígeno en nitrógeno","Libera energía al degradar glucosa","Convierte proteínas en ácidos grasos","La fotosíntesis almacena energía en compuestos orgánicos."]],"citogenetica":[["¿Quién introdujo el término cromosoma en 1888?","Heinrich Wilhelm Waldeyer","Gregor Mendel","Charles Darwin","James Watson","El término fue propuesto por von Waldeyer en 1888."],["¿Qué es un cariotipo?","Conjunto ordenado de cromosomas de una célula","Secuencia de aminoácidos","Lista de hormonas","Conjunto de órganos","El cariotipo permite observar número y morfología cromosómica."],["¿Qué es una aneuploidía?","Alteración del número de uno o varios cromosomas","Duplicación de todos los juegos cromosómicos","Cambio de una base sin alterar cromosomas","Pérdida de un aminoácido","La aneuploidía afecta cromosomas individuales."],["¿Qué proceso puede originar una trisomía?","No disyunción cromosómica","Traducción del ARN","Digestión celular","Entrecruzamiento normal exclusivamente","La no disyunción produce gametos con cromosomas de más o de menos."],["¿Qué cariotipo se asocia típicamente al síndrome de Turner?","45,X","47,XXY","47,+21","47,XYY","Turner se relaciona con monosomía total o parcial del X."],["¿Qué cariotipo corresponde al síndrome de Klinefelter clásico?","47,XXY","45,X","47,+13","46,XX","El patrón clásico presenta un cromosoma X adicional en varones."],["¿Qué trisomía se asocia al síndrome de Patau?","Trisomía 13","Trisomía 18","Trisomía 21","Trisomía X","Patau se asocia a una copia adicional del cromosoma 13."],["¿Qué trisomía se asocia al síndrome de Edwards?","Trisomía 18","Trisomía 13","Trisomía 21","Monosomía X","Edwards corresponde a trisomía 18."],["¿Qué es una translocación?","Traslado de un segmento a otro cromosoma","Giro de un segmento en el mismo cromosoma","Pérdida de un nucleótido","Duplicación de un centríolo","Una translocación implica intercambio o traslado entre cromosomas."],["¿Qué diferencia una transición de una transversión?","Transición sustituye purina por purina o pirimidina por pirimidina","Transición elimina un cromosoma","Transversión cambia solo el número cromosómico","Son sinónimos","Las transiciones conservan la clase química de la base."],["¿Cuál es un agente mutagénico químico?","Algunos compuestos alquilantes","Radiación ultravioleta","Rayos X","Radiación gamma","Los agentes alquilantes modifican químicamente las bases del ADN."],["¿Qué consecuencia puede tener una mutación en células germinales?","Puede transmitirse a la descendencia","Siempre afecta solo al individuo y nunca se hereda","Se convierte en hormona","No puede afectar al ADN","Las mutaciones germinales pueden pasar a los hijos."],["¿Qué caracteriza a una deleción cromosómica?","Pérdida de un segmento","Repetición de un segmento","Inversión de un segmento","Unión de cromosomas homólogos","La deleción elimina material genético."],["¿Qué representa 47,XY,+21?","Cariotipo masculino con trisomía 21","Cariotipo femenino con monosomía X","Cariotipo masculino XXY","Cariotipo con 46 cromosomas normales","La notación indica 47 cromosomas, XY y una copia extra del 21."],["¿Por qué se recomienda asesoramiento genético ante ciertos hallazgos cromosómicos?","Para explicar resultados, opciones y riesgos con información clara","Para garantizar que no habrá variaciones","Para sustituir toda atención médica","Para elegir características de una persona","El asesoramiento facilita decisiones informadas y apoyo no estigmatizante."]]};
